"""Tests for subject: traceback frame extraction and CI failure fingerprinting."""

import hashlib
import json

from subject import _extract_frames, compute_error_fingerprint


def _tb(*frames):
    """Build a realistic traceback string from (path, lineno, func) tuples."""
    lines = ["Traceback (most recent call last):"]
    for path, lineno, func in frames:
        lines.append(f'  File "{path}", line {lineno}, in {func}')
        lines.append(f"    {func}_body()")
    lines.append("ValueError: boom")
    return "\n".join(lines)


# --- _extract_frames ---


def test_extract_frames_single_frame():
    assert _extract_frames(_tb(("/app/pkg_a/foo.py", 10, "run"))) == ["pkg_a/foo.py:run"]


def test_extract_frames_uses_last_two_path_components():
    tb = _tb(("/srv/ci/ws/src/deep/nested/runner/executor.py", 3, "main"))
    assert _extract_frames(tb) == ["runner/executor.py:main"]


def test_extract_frames_relative_path():
    assert _extract_frames(_tb(("pkg_a/foo.py", 7, "run"))) == ["pkg_a/foo.py:run"]


def test_extract_frames_backslash_paths():
    tb = '  File "C:\\repo\\pkg_b\\bar.py", line 5, in main'
    assert _extract_frames(tb) == ["pkg_b/bar.py:main"]


def test_extract_frames_preserves_stack_order():
    tb = _tb(
        ("/srv/code/zzz/mod.py", 1, "alpha"),
        ("/srv/code/aaa/mod.py", 2, "beta"),
    )
    assert _extract_frames(tb) == ["zzz/mod.py:alpha", "aaa/mod.py:beta"]


def test_extract_frames_line_numbers_stripped():
    assert _extract_frames(_tb(("/p/mod_a.py", 3, "f"))) == _extract_frames(
        _tb(("/p/mod_a.py", 999, "f"))
    )


def test_extract_frames_distinguishes_same_basename_in_different_packages():
    tb = _tb(
        ("/ws/pkg_a/foo.py", 1, "handler"),
        ("/ws/pkg_b/foo.py", 2, "handler"),
    )
    assert _extract_frames(tb) == ["pkg_a/foo.py:handler", "pkg_b/foo.py:handler"]


def test_extract_frames_function_names_captured():
    tb = _tb(("/app/core/engine.py", 42, "execute_task"))
    assert _extract_frames(tb) == ["core/engine.py:execute_task"]


def test_extract_frames_no_frames_in_plain_output():
    assert _extract_frames("some plain output\nno traceback here 0x1 nope") == []


def test_extract_frames_empty_string():
    assert _extract_frames("") == []


# --- compute_error_fingerprint ---


def test_fingerprint_is_sha256_of_canonical_payload():
    tb = _tb(
        ("/app/services/worker.py", 12, "poll"),
        ("/app/services/runner.py", 34, "execute"),
    )
    expected_payload = json.dumps(
        {
            "frames": ["services/worker.py:poll", "services/runner.py:execute"],
            "tests": ["test_b", "test_a"],
        },
        sort_keys=True,
    )
    assert compute_error_fingerprint(tb, ["test_b", "test_a"]) == hashlib.sha256(
        expected_payload.encode()
    ).hexdigest()


def test_fingerprint_deterministic():
    tb = _tb(("/app/pkg/mod.py", 4, "go"))
    assert compute_error_fingerprint(tb, ["t"]) == compute_error_fingerprint(tb, ["t"])


def test_fingerprint_is_64_hex_chars():
    fp = compute_error_fingerprint(_tb(("/a/b.py", 1, "f")), [])
    assert len(fp) == 64
    assert all(c in "0123456789abcdef" for c in fp)


def test_fingerprint_independent_of_failing_test_order():
    tb = _tb(("/app/pkg/mod.py", 4, "go"))
    assert compute_error_fingerprint(tb, ["t_b", "t_a", "t_c"]) == compute_error_fingerprint(
        tb, ["t_c", "t_a", "t_b"]
    )


def test_fingerprint_sensitive_to_frame_order():
    tb1 = _tb(("/app/m/first.py", 1, "a"), ("/app/m/second.py", 2, "b"))
    tb2 = _tb(("/app/m/second.py", 2, "b"), ("/app/m/first.py", 1, "a"))
    assert compute_error_fingerprint(tb1, ["t"]) != compute_error_fingerprint(tb2, ["t"])


def test_fingerprint_sensitive_to_failing_tests():
    tb = _tb(("/app/m/x.py", 1, "a"))
    assert compute_error_fingerprint(tb, ["t1"]) != compute_error_fingerprint(tb, ["t2"])


def test_fingerprint_stable_across_line_numbers():
    assert compute_error_fingerprint(_tb(("/app/m/x.py", 1, "a")), ["t"]) == (
        compute_error_fingerprint(_tb(("/app/m/x.py", 50, "a")), ["t"])
    )


def test_fingerprint_ignores_memory_addresses():
    tb1 = _tb(("/app/pkg_a/foo.py", 10, "run")) + "\nRuntimeError: object at 0x7f3a1b2c3d40 failed"
    tb2 = _tb(("/app/pkg_a/foo.py", 10, "run")) + "\nRuntimeError: object at 0xdeadbeef42 failed"
    assert compute_error_fingerprint(tb1, ["t1"]) == compute_error_fingerprint(tb2, ["t1"])


def test_fingerprint_empty_input_matches_canonical_payload():
    expected = hashlib.sha256(
        json.dumps({"frames": [], "tests": []}, sort_keys=True).encode()
    ).hexdigest()
    assert compute_error_fingerprint("", []) == expected
